import pytest


def create_task(client, title="Original title"):
    response = client.post("/tasks", json={"title": title})
    assert response.status_code == 201
    return response.json()


def assert_persisted(client, task):
    response = client.get(f"/tasks/{task['id']}")
    assert response.status_code == 200
    assert response.json() == task


def test_update_title_trims_and_preserves_other_fields(client):
    original = create_task(client)

    response = client.patch(
        f"/tasks/{original['id']}", json={"title": "  Updated title \t\n"}
    )

    expected = {**original, "title": "Updated title"}
    assert response.status_code == 200
    assert response.json() == expected
    assert_persisted(client, expected)


def test_update_done_preserves_title_and_can_toggle_back(client):
    original = create_task(client)

    for done in (True, False):
        response = client.patch(
            f"/tasks/{original['id']}", json={"done": done}
        )
        expected = {**original, "done": done}
        assert response.status_code == 200
        assert response.json() == expected
        assert response.json()["done"] is done
        assert_persisted(client, expected)


def test_update_title_and_done_together(client):
    original = create_task(client)

    response = client.patch(
        f"/tasks/{original['id']}",
        json={"title": "  Completed task  ", "done": True},
    )

    expected = {**original, "title": "Completed task", "done": True}
    assert response.status_code == 200
    assert response.json() == expected
    assert_persisted(client, expected)


@pytest.mark.parametrize("title", ["x", "x" * 100])
def test_update_accepts_title_length_boundaries_after_trimming(client, title):
    original = create_task(client)

    response = client.patch(
        f"/tasks/{original['id']}", json={"title": f"  {title}  "}
    )

    expected = {**original, "title": title}
    assert response.status_code == 200
    assert response.json() == expected
    assert_persisted(client, expected)


@pytest.mark.parametrize("title", ["", " \t\n ", "x" * 101, f"  {'x' * 101}  "])
def test_invalid_title_rejects_entire_update_without_changing_done(client, title):
    original = create_task(client)

    response = client.patch(
        f"/tasks/{original['id']}", json={"title": title, "done": True}
    )

    assert response.status_code == 422
    assert "detail" in response.json()
    assert_persisted(client, original)


def test_empty_update_is_rejected_without_changing_task(client):
    original = create_task(client)

    response = client.patch(f"/tasks/{original['id']}", json={})

    assert response.status_code == 422
    assert "detail" in response.json()
    assert_persisted(client, original)


@pytest.mark.parametrize(
    "payload",
    [{"title": "New title"}, {"done": True}, {"title": "New title", "done": False}],
)
def test_valid_update_of_unknown_id_returns_not_found(client, payload):
    response = client.patch("/tasks/999999", json=payload)

    assert response.status_code == 404
    assert response.json() == {"detail": "Task not found"}


def test_update_cannot_change_identity_or_creation_timestamp(client):
    original = create_task(client)
    other = create_task(client, "Other task")

    response = client.patch(
        f"/tasks/{original['id']}",
        json={
            "title": "Changed title",
            "done": True,
            "id": other["id"],
            "created_at": "2000-01-01T00:00:00Z",
        },
    )

    expected = {**original, "title": "Changed title", "done": True}
    assert response.status_code == 200
    assert response.json() == expected
    assert_persisted(client, expected)
    assert_persisted(client, other)

    listing = client.get("/tasks")
    assert listing.status_code == 200
    assert listing.json() == [other, expected]
